-- Fix 74f after 73f: restart the CLD sync. The waiting rows land on the next sync and the DTs pick
-- them up; freshness returns to FRESH.
alter task {{DEMO_L0}}.SYNC.SYNC_L0 resume;
execute task {{DEMO_L0}}.SYNC.SYNC_L0;

insert into {{DEMO_DB}}.CONTROL.SCHEMA_CHANGE_LOG (SCENARIO, EVENT, GUARDRAIL, DETAIL, SOURCE)
values ('74f', 'FIX_APPLIED', 'G2', 'CLD sync restarted; waiting rows synced', 'PRESENTER');
